import type { IconComponent } from '@wix/wix-ui-icons-common/core';
import {
  NumberListThin,
  NumberListThinSmall,
  Objects,
  ObjectsSmall,
} from '@wix/wix-ui-icons-common/lazy';

import { PmNodeType } from './../../_shared/pm-node-types.js';
import type { Node as PmNode } from './../../tiptap/pm/model.js';

import { DATA_HOOKS } from '../data-hooks.js';

export type NumberedMode = 'numbers' | 'shapes';

export const SMART_BLOCK_NUMBERED_DROPDOWN_ID = 'smart-block-numbered-dropdown';

export const NUMBERED_MODE_OPTIONS: Record<
  NumberedMode,
  {
    dataHook: string;
    labelKey: string;
    icon: IconComponent;
    iconMobile: IconComponent;
  }
> = {
  numbers: {
    dataHook: DATA_HOOKS.NUMBERED_OPTION_NUMBERS,
    labelKey: 'SmartBlock_Numbered_Mode_Numbers',
    icon: NumberListThinSmall,
    iconMobile: NumberListThin,
  },
  shapes: {
    dataHook: DATA_HOOKS.NUMBERED_OPTION_SHAPES,
    labelKey: 'SmartBlock_Numbered_Mode_Shapes',
    icon: ObjectsSmall,
    iconMobile: Objects,
  },
};

// Shapes mode is active when any cell in the block has an explicit shape.
// The default shape is rendered for unshaped cells without being stored in the document.
export const getSelectedMode = (smartBlockNode?: PmNode | null): NumberedMode => {
  if (!smartBlockNode) {
    return 'numbers';
  }

  let hasAnyShape = false;
  smartBlockNode.forEach(child => {
    if (child.type.name === PmNodeType.SMART_BLOCK_CELL && child.attrs.shape) {
      hasAnyShape = true;
    }
  });

  return hasAnyShape ? 'shapes' : 'numbers';
};
