import { PmNodeType } from './../../_shared/pm-node-types.js';
import type { Node as PmNode } from './../../tiptap/pm/model.js';

export const getShapeColors = (node: PmNode): string[] => {
  if (node.type.name === PmNodeType.SMART_BLOCK_CELL) {
    const color = node.attrs?.shapeColor as string | null | undefined;
    return color ? [color] : [];
  }
  // For block: collect one color per cell (skipping cells with no override).
  const colors: string[] = [];
  node.forEach((child: PmNode) => {
    if (child.type.name !== PmNodeType.SMART_BLOCK_CELL) {
      return;
    }
    const color = child.attrs?.shapeColor as string | null | undefined;
    if (color) {
      colors.push(color);
    }
  });
  return colors;
};

// Returns true if any cell in the node falls back to the theme default (no explicit shapeColor).
export const hasDefaultShapeColor = (node: PmNode): boolean => {
  if (node.type.name === PmNodeType.SMART_BLOCK_CELL) {
    return !node.attrs?.shapeColor;
  }
  let found = false;
  node.forEach((child: PmNode) => {
    if (child.type.name === PmNodeType.SMART_BLOCK_CELL && !child.attrs?.shapeColor) {
      found = true;
    }
  });
  return found;
};

export const getEffectiveShapeButtonColors = ({
  colors,
  hasDefaultColors = false,
  labelColor,
}: {
  colors: string[];
  hasDefaultColors?: boolean;
  labelColor?: string;
}): string[] => {
  // Include labelColor when all cells use the default or when some cells use it alongside
  // explicit custom colors — so the button always reflects the full set of active colors.
  if (colors.length === 0 || hasDefaultColors) {
    return labelColor ? [...new Set([...colors, labelColor])] : colors;
  }
  return colors;
};
