import { ColorBucket } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useEffect, useMemo, useState } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { useModalService } from './../../../ricos-modals/modal-service-provider.js';
import type { SmartBlockData_Type } from './../../../ricos-schema/next-schema/index.js';
import { mapColorPaletteToCustomStyles } from './../../../ricos-styles/themeStrategy/generators/palette.js';
import type { IToolbarItem } from './../../../ricos-types/index.js';
import { ColorSwatch } from './../../../_shared/plugin-toolbar/color-swatch.js';
import { ToolbarButton as ToolbarButtonComponent } from './../../../_shared/toolbar-button/toolbar-button.js';

import { DATA_HOOKS } from '../../data-hooks.js';
import { getCellColorAttr } from '../../utils/variant-features.js';

export const SmartBlockColorButton: FC<{ toolbarItem: IToolbarItem }> = ({ toolbarItem }) => {
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);
  const [isActive, setIsActive] = useState(toolbarItem.attributes.active);
  const modalService = useModalService();
  const { t, theme } = useContext(RicosContext);

  useEffect(() => {
    const handler = () => setIsActive(Boolean(toolbarItem.attributes.active));
    const openedSub = modalService.onModalOpened(handler);
    const closedSub = modalService.onModalClosed(handler);
    return () => {
      openedSub.cancel();
      closedSub.cancel();
    };
  }, [modalService, toolbarItem.attributes.active]);

  const variant = toolbarItem.attributes.variant as SmartBlockData_Type | undefined;

  const themeSmartBlock = useMemo(() => {
    if (!variant) {
      return undefined;
    }
    return (
      theme?.customStyles?.smartBlock ??
      (theme?.colorPalette
        ? mapColorPaletteToCustomStyles(theme.colorPalette).smartBlock
        : undefined)
    );
  }, [theme?.customStyles?.smartBlock, theme?.colorPalette, variant]);

  const colors: string[] = toolbarItem.attributes.colors ?? [];

  const effectiveColors = useMemo(() => {
    if (colors.length > 0) {
      return colors;
    }
    if (!variant || !themeSmartBlock) {
      return [];
    }
    const colorAttr = getCellColorAttr(variant);
    const themeColor = themeSmartBlock[colorAttr];
    return themeColor ? [themeColor] : [];
  }, [colors, variant, themeSmartBlock]);

  const hasColors = effectiveColors.length > 0;

  return (
    <ToolbarButtonComponent
      ref={setReferenceElement}
      prefix={hasColors ? () => <ColorSwatch colors={effectiveColors} /> : ColorBucket}
      active={isActive}
      onClick={() => toolbarItem.commands.click({ referenceElement })}
      dataHook={DATA_HOOKS.COLOR_BUTTON}
      tooltip={t('SmartBlock_Toolbar_Color_Tooltip')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
