import { BorderWidth } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useEffect, useState } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { useModalService } from './../../../ricos-modals/modal-service-provider.js';
import type { IToolbarItem } from './../../../ricos-types/index.js';
import { ToolbarButton as ToolbarButtonComponent } from './../../../_shared/toolbar-button/toolbar-button.js';

import { DATA_HOOKS } from '../../data-hooks.js';

export const BorderSettingsButton: FC<{ toolbarItem: IToolbarItem }> = ({ toolbarItem }) => {
  const { isMobile, t } = useContext(RicosContext);
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);
  const [isActive, setIsActive] = useState(toolbarItem.attributes.active);
  const modalService = useModalService();

  const onClick = () => toolbarItem.commands.click({ referenceElement, isMobile });

  useEffect(() => {
    const handler = () => setIsActive(Boolean(toolbarItem.attributes.active));
    const openedSub = modalService.onModalOpened(handler);
    const closedSub = modalService.onModalClosed(handler);
    return () => {
      openedSub.cancel();
      closedSub.cancel();
    };
  }, [modalService, toolbarItem.attributes.active]);

  return (
    <ToolbarButtonComponent
      ref={setReferenceElement}
      prefix={BorderWidth}
      active={isActive}
      onClick={onClick}
      dataHook={DATA_HOOKS.DESIGN_BUTTON}
      tooltip={t('SmartBlock_Toolbar_Borders_Tooltip')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
