import type { SmartBlockData_Type } from './../../ricos-schema/next-schema/generated/ricos_document.js';
import type { Resolver } from './../../ricos-types/index.js';
import { PmNodeType } from './../../_shared/pm-node-types.js';
import type { Editor } from './../../tiptap/core/index.js';
import { findParentNodeClosestToPos } from './../../tiptap/core/index.js';
import type { Node as PmNode } from './../../tiptap/pm/model.js';
import { NodeSelection } from './../../tiptap/pm/state.js';

import { MAX_ITEMS } from '../consts.js';
import {
  hasBlockBorderSupport,
  hasCellBorderSupport,
  hasColumnSizeSupport,
  hasShapeSupport,
  hasOrientation,
} from '../utils/variant-features.js';

// ── Shared resolvers ─────────────────────────────────────────────────

export const getSelectedSmartNode: Resolver<PmNode | undefined> = (_, __, editor) => {
  if (!editor?.state) {
    return undefined;
  }
  const selection = editor.state.selection;
  if (
    selection instanceof NodeSelection &&
    selection.node?.type?.name === PmNodeType.SMART_BLOCK_CELL
  ) {
    return selection.node;
  }
  return getSmartBlockNode(_, __, editor);
};

// Animation applies to the whole smart block — hide the button on cell
// selections, otherwise target the block (NodeSelection or closest ancestor).
export const getSmartBlockForAnimation: Resolver<PmNode | undefined> = (_, __, editor) => {
  const selection = editor?.state?.selection;
  if (
    selection instanceof NodeSelection &&
    selection.node?.type?.name === PmNodeType.SMART_BLOCK_CELL
  ) {
    return undefined;
  }
  return getSmartBlockNode(_, __, editor);
};

// ── Block-level resolvers ────────────────────────────────────────────

export const getSmartBlockNode: Resolver<PmNode | undefined> = (_, __, editor) => {
  if (!editor?.state) {
    return undefined;
  }

  const { selection } = editor.state;

  if (selection instanceof NodeSelection && selection.node) {
    if (selection.node.type?.name === PmNodeType.SMART_BLOCK) {
      return selection.node;
    }
  }

  const result = findParentNodeClosestToPos(
    editor.state.doc.resolve(selection.from),
    node => node.type?.name === PmNodeType.SMART_BLOCK
  );

  return result?.node;
};

export const isLayoutSelected: Resolver = (_, __, editor) => {
  if (!editor?.state) {
    return false;
  }

  const selection = editor.state.selection as Record<string, any>;

  if (selection.node?.type?.name === PmNodeType.SMART_BLOCK_CELL) {
    return false;
  }

  if (selection.node?.type?.name === PmNodeType.SMART_BLOCK) {
    return true;
  }

  if (!selection.node && selection.$from) {
    const closestParent = findParentNodeClosestToPos(
      selection.$from,
      node => node.type.name === PmNodeType.SMART_BLOCK
    );
    return !!closestParent;
  }

  return false;
};

export const isLayoutSelectedAndColumnSizeVariant: Resolver = (_, __, editor) => {
  const node = getSmartBlockNode(_, __, editor);
  const variant = node?.attrs?.type as SmartBlockData_Type;
  if (!isLayoutSelected(_, __, editor) || !variant) {
    return false;
  }
  return hasColumnSizeSupport(variant);
};

export const isLayoutSelectedAndOrientationVariant: Resolver = (_, __, editor) => {
  const node = getSmartBlockNode(_, __, editor);
  const variant = node?.attrs?.type as SmartBlockData_Type;
  if (!isLayoutSelected(_, __, editor) || !variant) {
    return false;
  }
  return hasOrientation(variant);
};

export const isLayoutSelectedAndNumberedVariants: Resolver = (_, __, editor) => {
  const node = getSmartBlockNode(_, __, editor);
  const variant = node?.attrs?.type as SmartBlockData_Type;
  if (!isLayoutSelected(_, __, editor) || !variant) {
    return false;
  }
  return hasShapeSupport(variant);
};

// ── Cell-level resolvers ─────────────────────────────────────────────

export const isBorderSupported: Resolver = (_, __, editor) => {
  if (isCellSelected(_, __, editor)) {
    const variant = getParentVariant(editor);
    return !!variant && hasCellBorderSupport(variant);
  }
  const node = getSmartBlockNode(_, __, editor);
  const variant = node?.attrs?.type as SmartBlockData_Type;
  if (!isLayoutSelected(_, __, editor) || !variant) {
    return false;
  }
  return hasCellBorderSupport(variant) || hasBlockBorderSupport(variant);
};

export const isCellSelected: Resolver = (_, __, editor) => {
  if (!editor?.state) {
    return false;
  }
  const selection = editor.state.selection as Record<string, any>;
  return selection.node?.type?.name === PmNodeType.SMART_BLOCK_CELL;
};

export const isCellOrLayoutSelected: Resolver = (_, __, editor) => {
  return isLayoutSelected(_, __, editor) || isCellSelected(_, __, editor);
};

export const canAddCell: Resolver = (_, __, editor) => {
  if (!editor?.state) {
    return false;
  }
  const { selection } = editor.state;
  if (!(selection instanceof NodeSelection)) {
    return false;
  }
  if (selection.node?.type?.name !== PmNodeType.SMART_BLOCK_CELL) {
    return false;
  }

  const parent = findParentNodeClosestToPos(
    editor.state.doc.resolve(selection.from),
    node => node.type?.name === PmNodeType.SMART_BLOCK
  );
  return !!parent && parent.node.childCount < MAX_ITEMS;
};

export const getParentVariant = (editor: Editor | undefined): SmartBlockData_Type | undefined => {
  if (!editor?.state) {
    return undefined;
  }
  const { selection } = editor.state;
  const nodeSelection = selection as Record<string, any>;
  if (nodeSelection.node?.type?.name !== PmNodeType.SMART_BLOCK_CELL) {
    return undefined;
  }

  const result = findParentNodeClosestToPos(
    editor.state.doc.resolve(selection.from),
    (node: any) => node.type?.name === PmNodeType.SMART_BLOCK
  );
  return result?.node?.attrs?.type as SmartBlockData_Type;
};

export const isCellInLabelVariantWithoutImage: Resolver = (_, __, editor) => {
  if (!editor?.state) {
    return false;
  }
  const variant = getParentVariant(editor);
  if (!variant || !hasShapeSupport(variant)) {
    return false;
  }

  const selection = editor.state.selection as Record<string, any>;
  return !selection.node?.attrs?.shape;
};

export const isCellInLabelVariantWithImage: Resolver = (_, __, editor) => {
  if (!editor?.state) {
    return false;
  }
  const variant = getParentVariant(editor);
  if (!variant || !hasShapeSupport(variant)) {
    return false;
  }

  const selection = editor.state.selection as Record<string, any>;
  return !!selection.node?.attrs?.shape;
};

export const isLayoutInLabelVariantWithImage: Resolver = (_, __, editor) => {
  if (!editor?.state) {
    return false;
  }
  const node = getSmartBlockNode(_, __, editor);
  const variant = node?.attrs?.type as SmartBlockData_Type | undefined;
  if (!isLayoutSelected(_, __, editor) || !variant || !hasShapeSupport(variant)) {
    return false;
  }

  let hasShape = false;
  node?.forEach(child => {
    if (child.type?.name === PmNodeType.SMART_BLOCK_CELL && child.attrs?.shape) {
      hasShape = true;
    }
  });

  return hasShape;
};
