import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../../ricos-modals/modal-service-provider.js';
import type { IToolbarItem } from './../../../ricos-types/index.js';
import { DropdownButton } from './../../../_shared/dropdown-button.js';
import type { Node as PmNode } from './../../../tiptap/pm/model.js';

import { DATA_HOOKS } from '../../data-hooks.js';
import {
  getSelectedMode,
  NUMBERED_MODE_OPTIONS,
  SMART_BLOCK_NUMBERED_DROPDOWN_ID,
} from '../numbered-mode-options.js';

export const NumberedDropdownButton: React.FC<{ toolbarItem: IToolbarItem }> = ({
  toolbarItem,
}) => {
  const isModalOpen = useModalState(getIsModalOpen(SMART_BLOCK_NUMBERED_DROPDOWN_ID));
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);
  const { t } = useContext(RicosContext);

  const mode = getSelectedMode(toolbarItem.attributes.selectedNode as PmNode | undefined);

  return (
    <DropdownButton
      dataHook={DATA_HOOKS.NUMBERED_DROPDOWN_BUTTON}
      active={isModalOpen}
      onClick={() => toolbarItem.commands?.click({ referenceElement })}
      icon={NUMBERED_MODE_OPTIONS[mode].icon}
      ref={setReferenceElement}
      tooltip={t(NUMBERED_MODE_OPTIONS[mode].labelKey)}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
