import { Duplicate } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import type { IToolbarItem } from './../../../ricos-types/index.js';
import { ToolbarButton as ToolbarButtonComponent } from './../../../_shared/toolbar-button/toolbar-button.js';

import { DATA_HOOKS } from '../../data-hooks.js';

export const DuplicateCellButton: React.FC<{ toolbarItem: IToolbarItem }> = ({ toolbarItem }) => {
  const { t } = useContext(RicosContext) || {};

  return (
    <ToolbarButtonComponent
      prefix={Duplicate}
      disabled={!toolbarItem.attributes.canAddCell}
      onClick={() => toolbarItem.commands.click()}
      dataHook={DATA_HOOKS.CELL_DUPLICATE_BUTTON}
      tooltip={t('SmartBlock_CellDuplicate_Tooltip')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
