import type { IconComponent } from '@wix/wix-ui-icons-common/core';
import React, { useContext, useState } from 'react';

import { ALIGNMENT_BUTTON_CONFIGS } from './../../ricos-common-plugins/text-align/dropdown/consts.js';
import TextAlignmentDropdown from './../../ricos-common-plugins/text-align/dropdown/text-alignment-dropdown.js';
import { getEnumByStyle } from './../../ricos-common-plugins/text-align/get-enum-by-style.js';
import { RicosContext } from './../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../ricos-modals/modal-service-provider.js';
import { TextStyle_TextAlignment } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { IToolbarItem, RicosServices, TextAlignment } from './../../ricos-types/index.js';
import { createPluginToolbarButton } from './../../_shared/create-plugin-toolbar-button.js';
import { DropdownButton } from './../../_shared/dropdown-button.js';
import { PmNodeType } from './../../_shared/pm-node-types.js';
import type { Editor } from './../../tiptap/core/index.js';
import { findParentNodeClosestToPos } from './../../tiptap/core/index.js';
import type { Node as PmNode } from './../../tiptap/pm/model.js';
import { NodeSelection, TextSelection } from './../../tiptap/pm/state.js';

import { DATA_HOOKS } from '../data-hooks.js';
import { getCircleCellStyle } from '../utils/cell-position.js';
import { isCellOrLayoutSelected } from './resolvers.js';

// Mirrors the viewer's circle-side → alignment mapping in
// `viewer/smart-block-cell.tsx`. Used to surface the visual alignment for AUTO
// paragraphs in CIRCLE cells (whose text-align is driven by cell CSS, not by
// paragraph data).
const CIRCLE_SIDE_TO_ALIGNMENT: Record<'left' | 'right' | 'bottom', TextAlignment> = {
  left: 'right',
  right: 'left',
  bottom: 'center',
};

const SMART_BLOCK_TEXT_ALIGNMENT_MODAL_ID = 'smart-block-text-alignment-modal';

export const createTextAlignmentButton = ({ services }: { services: RicosServices }) =>
  createPluginToolbarButton({
    id: 'smartBlockTextAlignment',
    type: 'dropdown',
    tooltip: 'AlignTextDropdownButton_Tooltip',
    getIcon: ({ attributes }) => {
      const alignment = (attributes?.selectedAlignment as TextAlignment) || 'left';
      return ALIGNMENT_BUTTON_CONFIGS[alignment]?.icon;
    },
    dataHook: DATA_HOOKS.TEXT_ALIGN_DROPDOWN_BUTTON,
    attributes: {
      visible: isCellOrLayoutSelected,
      selectedAlignment: (_, __, editor) => {
        const scope = resolveAlignmentScope(editor);
        if (!scope) {
          return 'left';
        }
        const fallback = editor ? getCircleCellFallbackAlignment(editor, scope) : 'left';
        return getScopedAlignment(scope.targetNode, fallback);
      },
    },
    renderer: toolbarItem => <SmartBlockTextAlignmentButton toolbarItem={toolbarItem} />,
    // Cast so `getComponentProps` is typed to return `options` (the shape the wixel
    // alignment branch in asset-header reads — matches DIVIDER.alignment). The `command`
    // below converts `options` → `dropdownOptions` before handing them to the actual
    // TextAlignmentDropdown component for the ricos-native modal.
    Component: TextAlignmentDropdown as unknown as React.ComponentType<
      Omit<React.ComponentProps<typeof TextAlignmentDropdown>, 'dropdownOptions'> & {
        options: {
          type: 'button';
          id: string;
          dataHook: string;
          label: string;
          icon: IconComponent;
          iconMobile: IconComponent;
        }[];
      }
    >,
    command: props => {
      const {
        modals,
        referenceElement,
        getComponentProps,
        tiptapEditor,
        attributes,
        publicCommands,
      } = props;

      const componentProps = getComponentProps?.({
        tiptapEditor,
        attributes,
        publicCommands,
        t: services.t,
        modals,
        languageDir: services.context.languageDir,
      });

      if (!componentProps) {
        return;
      }

      const { options, ...rest } = componentProps;

      modals.togglePluginPanel({
        id: SMART_BLOCK_TEXT_ALIGNMENT_MODAL_ID,
        Component: TextAlignmentDropdown,
        componentProps: {
          ...rest,
          dropdownOptions: options.map(({ id, dataHook, label, icon, iconMobile }) => ({
            id,
            dataHook,
            label,
            icon,
            iconMobile,
          })),
        },
        isMobile: services.context.isMobile,
        positioning: { referenceElement, placement: 'bottom' },
      });
    },
    getComponentProps: ({ tiptapEditor, attributes, t, modals }) => {
      const scope = resolveAlignmentScope(tiptapEditor);

      return {
        options: Object.values(ALIGNMENT_BUTTON_CONFIGS).map(item => ({
          type: 'button' as const,
          id: item.commandKey,
          dataHook: item.dataHook,
          label: t(item.text),
          icon: item.icon,
          iconMobile: item.iconMobile,
        })),
        onSelect: (alignment: string) => {
          if (!scope) {
            return;
          }

          applyAlignmentInScope(scope, alignment, tiptapEditor);
        },
        selectedId: (attributes?.selectedAlignment as string) || 'left',
        closeModal: () => modals.closeModal(SMART_BLOCK_TEXT_ALIGNMENT_MODAL_ID),
      };
    },
  });

const ALIGNABLE_NODE_TYPES = new Set<string>([
  PmNodeType.PARAGRAPH,
  PmNodeType.HEADING,
  PmNodeType.LIST_ITEM,
  PmNodeType.CODE_BLOCK,
  PmNodeType.BLOCKQUOTE,
  PmNodeType.CAPTION,
]);

type AlignmentScope =
  | {
      type: 'cell';
      selectionPos: number;
      targetPos: number;
      targetNode: PmNode;
    }
  | {
      type: 'block';
      selectionPos: number;
      targetPos: number;
      targetNode: PmNode;
    };

const resolveAlignmentScope = (editor: Editor | undefined): AlignmentScope | null => {
  if (!editor?.state) {
    return null;
  }

  const { selection, doc } = editor.state;

  if (
    selection instanceof NodeSelection &&
    selection.node?.type?.name === PmNodeType.SMART_BLOCK_CELL
  ) {
    return {
      type: 'cell' as const,
      selectionPos: selection.from,
      targetPos: selection.from,
      targetNode: selection.node,
    };
  }

  if (selection instanceof NodeSelection && selection.node?.type?.name === PmNodeType.SMART_BLOCK) {
    return {
      type: 'block' as const,
      selectionPos: selection.from,
      targetPos: selection.from,
      targetNode: selection.node,
    };
  }

  const smartBlock = findParentNodeClosestToPos(
    doc.resolve(selection.from),
    node => node.type.name === PmNodeType.SMART_BLOCK
  );

  if (!smartBlock) {
    return null;
  }

  return {
    type: 'block' as const,
    selectionPos: selection.from,
    targetPos: smartBlock.pos,
    targetNode: smartBlock.node,
  };
};

const applyAlignmentInScope = (
  scope: AlignmentScope,
  alignment: string,
  editor: Editor
): boolean => {
  const textAlignment = getEnumByStyle(alignment, TextStyle_TextAlignment.UNRECOGNIZED);

  if (textAlignment === TextStyle_TextAlignment.UNRECOGNIZED) {
    return false;
  }

  return editor
    .chain()
    .focus(undefined, { scrollIntoView: false })
    .command(({ tr }) => {
      scope.targetNode.descendants((child: PmNode, pos: number) => {
        if (!ALIGNABLE_NODE_TYPES.has(child.type.name)) {
          return true;
        }

        tr.setNodeMarkup(scope.targetPos + pos + 1, undefined, {
          ...child.attrs,
          textStyle: {
            ...(child.attrs.textStyle ?? {}),
            textAlignment,
          },
        });

        return true;
      });

      if (scope.type === 'cell') {
        tr.setSelection(NodeSelection.create(tr.doc, scope.selectionPos));
      } else {
        tr.setSelection(TextSelection.near(tr.doc.resolve(scope.selectionPos)));
      }

      return true;
    })
    .run();
};

const getNormalizedAlignment = (
  alignment: string | undefined,
  fallback: TextAlignment
): TextAlignment => {
  if (!alignment) {
    return fallback;
  }
  const normalizedAlignment = alignment.toLowerCase();
  return normalizedAlignment === 'auto' ? fallback : (normalizedAlignment as TextAlignment);
};

const getScopedAlignment = (node: PmNode, fallback: TextAlignment = 'left'): TextAlignment => {
  let scopedAlignment: TextAlignment = fallback;

  node.descendants((child: PmNode) => {
    if (child.type.name !== PmNodeType.PARAGRAPH && child.type.name !== PmNodeType.HEADING) {
      return true;
    }

    scopedAlignment = getNormalizedAlignment(child.attrs.textStyle?.textAlignment, fallback);
    return false;
  });

  return scopedAlignment;
};

// For a CIRCLE cell scope, returns the CSS-driven text alignment for that cell
// (left side → right, right side → left, bottom → center). Used as the fallback
// so the toolbar reflects the cell's visual alignment when the paragraph's own
// textAlignment is AUTO. Returns 'left' for any non-CIRCLE-cell scope.
const getCircleCellFallbackAlignment = (editor: Editor, scope: AlignmentScope): TextAlignment => {
  if (scope.type !== 'cell') {
    return 'left';
  }
  const $pos = editor.state.doc.resolve(scope.targetPos);
  const parent = $pos.parent;
  if (parent.type.name !== PmNodeType.SMART_BLOCK || parent.attrs.type !== 'CIRCLE') {
    return 'left';
  }
  const cellIndex = $pos.index();
  const totalCells = parent.childCount;
  return CIRCLE_SIDE_TO_ALIGNMENT[getCircleCellStyle(cellIndex, totalCells).side];
};

const SmartBlockTextAlignmentButton: React.FC<{ toolbarItem: IToolbarItem }> = ({
  toolbarItem,
}) => {
  const isModalOpen = useModalState(getIsModalOpen(SMART_BLOCK_TEXT_ALIGNMENT_MODAL_ID));
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);
  const { t } = useContext(RicosContext);

  return (
    <DropdownButton
      ref={setReferenceElement}
      active={isModalOpen}
      tooltip={t('AlignTextDropdownButton_Tooltip')}
      onClick={() => toolbarItem.commands?.click({ referenceElement })}
      icon={
        ALIGNMENT_BUTTON_CONFIGS[toolbarItem.attributes.selectedAlignment as TextAlignment].icon
      }
      dataHook={DATA_HOOKS.TEXT_ALIGN_DROPDOWN_BUTTON}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
