import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { SmartBlockData_Orientation } from './../../ricos-schema/next-schema/index.js';
import type { RicosServices } from './../../ricos-types/index.js';
import { createPluginToolbarButton } from './../../_shared/create-plugin-toolbar-button.js';
import { DropdownModal } from './../../_shared/dropdown-modal/dropdown-modal.js';
import { ListItemSelect } from './../../_shared/list-item-select/list-item-select.js';

import { DATA_HOOKS } from '../data-hooks.js';
import { OrientationDropdownButton } from './buttons/orientation-dropdown-button.js';
import {
  getSelectedOrientation,
  ORIENTATION_OPTIONS,
  SMART_BLOCK_ORIENTATION_DROPDOWN_ID,
} from './orientation-options.js';
import { getSmartBlockNode, isLayoutSelectedAndOrientationVariant } from './resolvers.js';

export const createOrientationDropdownButton = ({ services }: { services: RicosServices }) =>
  createPluginToolbarButton({
    id: 'smartBlockOrientation',
    type: 'dropdown',
    getIcon: ({ attributes }) =>
      ORIENTATION_OPTIONS[getSelectedOrientation(attributes.selectedNode?.attrs?.orientation)].icon,
    tooltip: 'SmartBlock_Toolbar_Orientation_Tooltip',
    dataHook: DATA_HOOKS.DIRECTION_DROPDOWN_BUTTON,
    attributes: {
      selectedNode: getSmartBlockNode,
      visible: isLayoutSelectedAndOrientationVariant,
      active: (_, { modals }) => Boolean(modals?.getModal(SMART_BLOCK_ORIENTATION_DROPDOWN_ID)),
    },
    renderer: toolbarItem => <OrientationDropdownButton toolbarItem={toolbarItem} />,
    Component: OrientationDropdown,
    command: props => {
      const {
        modals,
        referenceElement,
        getComponentProps,
        tiptapEditor,
        attributes,
        publicCommands,
      } = props;

      const componentProps = getComponentProps?.({
        tiptapEditor,
        attributes,
        publicCommands,
        t: services.t,
        modals,
        languageDir: services.context.languageDir,
      });

      if (!componentProps) {
        return;
      }

      modals.isModalOpen(SMART_BLOCK_ORIENTATION_DROPDOWN_ID)
        ? modals.closeModal(SMART_BLOCK_ORIENTATION_DROPDOWN_ID)
        : modals.openModal({
            id: SMART_BLOCK_ORIENTATION_DROPDOWN_ID,
            Component: OrientationDropdown,
            componentProps,
            layout: services.context.isMobile ? 'drawer' : 'floating',
            positioning: { referenceElement, placement: 'bottom' },
            type: 'exclusive',
          });
    },
    getComponentProps: ({ tiptapEditor, attributes, t, modals }) => ({
      dropdownOptions: (
        Object.entries(ORIENTATION_OPTIONS) as [
          SmartBlockData_Orientation,
          (typeof ORIENTATION_OPTIONS)[SmartBlockData_Orientation],
        ][]
      ).map(([id, option]) => ({
        id,
        dataHook: option.dataHook,
        label: t(option.labelKey),
        icon: option.icon,
        iconMobile: option.iconMobile,
      })),
      onSelect: (orientation: SmartBlockData_Orientation) => {
        tiptapEditor.commands.setSmartBlockOrientation(orientation);
        modals.closeModal(SMART_BLOCK_ORIENTATION_DROPDOWN_ID);
      },
      selectedId: getSelectedOrientation(attributes.selectedNode?.attrs?.orientation),
      closeModal: () => modals.closeModal(SMART_BLOCK_ORIENTATION_DROPDOWN_ID),
    }),
  });

type OrientationDropdownProps = {
  dropdownOptions: {
    id: SmartBlockData_Orientation;
    dataHook: string;
    label: string;
    icon: React.ComponentType;
    iconMobile: React.ComponentType;
  }[];
  onSelect: (value: SmartBlockData_Orientation) => void;
  selectedId?: SmartBlockData_Orientation;
  closeModal: () => void;
};

const OrientationDropdown: React.FC<OrientationDropdownProps> = ({
  dropdownOptions,
  onSelect,
  selectedId,
  closeModal,
}) => {
  const { t, isMobile } = useContext(RicosContext);

  return (
    <DropdownModal
      title={t('SmartBlock_Toolbar_Orientation_Tooltip')}
      onCloseButtonClick={closeModal}
      options={dropdownOptions.map(
        ({ id, dataHook, label, icon: Icon, iconMobile: IconMobile }) => (
          <ListItemSelect
            key={id}
            dataHook={dataHook}
            prefix={isMobile && IconMobile ? <IconMobile /> : Icon ? <Icon /> : null}
            title={label}
            selected={id === selectedId}
            onSelect={() => onSelect(id)}
          />
        )
      )}
    />
  );
};
