import type { IconComponent } from '@wix/wix-ui-icons-common/core';
import {
  DistributeCenter,
  DistributeCenterSmall,
  DistributeFullWidth,
  DistributeFullWidthSmall,
  DistributeVertically,
  DistributeVerticallySmall,
  SizeAndRatio,
  SizeAndRatioSmall,
} from '@wix/wix-ui-icons-common/lazy';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../ricos-modals/modal-service-provider.js';
import type { SmartBlockData_ColumnSize } from './../../ricos-schema/next-schema/index.js';
import type { IToolbarItem, RicosServices } from './../../ricos-types/index.js';
import { createPluginToolbarButton } from './../../_shared/create-plugin-toolbar-button.js';
import { DropdownButton } from './../../_shared/dropdown-button.js';
import { DropdownModal } from './../../_shared/dropdown-modal/dropdown-modal.js';
import { ListItemSelect } from './../../_shared/list-item-select/list-item-select.js';
import type { Node as PmNode } from './../../tiptap/pm/model.js';

import { DATA_HOOKS } from '../data-hooks.js';
import { getSmartBlockNode, isLayoutSelectedAndColumnSizeVariant } from './resolvers.js';

const SMART_BLOCK_COLUMN_SIZE_DROPDOWN_ID = 'smart-block-column-size-dropdown';

const COLUMN_SIZE_OPTIONS: Record<
  SmartBlockData_ColumnSize,
  {
    label: string;
    dataHook: string;
    icon: IconComponent;
    iconMobile: IconComponent;
  }
> = {
  SMALL: {
    label: 'SmartBlock_ColumnSize_Small',
    dataHook: DATA_HOOKS.COLUMN_SIZE_OPTION_SMALL,
    icon: DistributeCenterSmall,
    iconMobile: DistributeCenter,
  },
  MEDIUM: {
    label: 'SmartBlock_ColumnSize_Medium',
    dataHook: DATA_HOOKS.COLUMN_SIZE_OPTION_MEDIUM,
    icon: DistributeVerticallySmall,
    iconMobile: DistributeVertically,
  },
  LARGE: {
    label: 'SmartBlock_ColumnSize_Large',
    dataHook: DATA_HOOKS.COLUMN_SIZE_OPTION_LARGE,
    icon: SizeAndRatioSmall,
    iconMobile: SizeAndRatio,
  },
  EXTRA_LARGE: {
    label: 'SmartBlock_ColumnSize_ExtraLarge',
    dataHook: DATA_HOOKS.COLUMN_SIZE_OPTION_EXTRA_LARGE,
    icon: DistributeFullWidthSmall,
    iconMobile: DistributeFullWidth,
  },
};

const getSelectedColumnSize = (selectedNode?: PmNode | null): SmartBlockData_ColumnSize =>
  (selectedNode?.attrs?.columnSize as SmartBlockData_ColumnSize) || 'MEDIUM';

export const createColumnSizeButton = ({ services }: { services: RicosServices }) =>
  createPluginToolbarButton({
    id: 'smartBlockColumnSize',
    type: 'dropdown',
    getIcon: ({ attributes }) =>
      COLUMN_SIZE_OPTIONS[getSelectedColumnSize(attributes.selectedNode as PmNode | undefined)]
        .icon,
    tooltip: 'SmartBlock_Toolbar_ColumnSize_Tooltip',
    dataHook: DATA_HOOKS.COLUMN_SIZE_DROPDOWN_BUTTON,
    attributes: {
      selectedNode: getSmartBlockNode,
      visible: isLayoutSelectedAndColumnSizeVariant,
      active: (_, { modals }) => Boolean(modals?.getModal(SMART_BLOCK_COLUMN_SIZE_DROPDOWN_ID)),
    },
    renderer: toolbarItem => (
      <ColumnSizeButton toolbarItem={toolbarItem} id={SMART_BLOCK_COLUMN_SIZE_DROPDOWN_ID} />
    ),
    Component: ColumnSizeDropdown,
    command: props => {
      const {
        modals,
        referenceElement,
        getComponentProps,
        tiptapEditor,
        attributes,
        publicCommands,
      } = props;
      const selectedNode = attributes.selectedNode as PmNode | undefined;

      if (!selectedNode) {
        return;
      }

      const componentProps = getComponentProps?.({
        tiptapEditor,
        attributes,
        publicCommands,
        t: services.t,
        modals,
        languageDir: services.context.languageDir,
      });

      if (!componentProps) {
        return;
      }

      modals.isModalOpen(SMART_BLOCK_COLUMN_SIZE_DROPDOWN_ID)
        ? modals.closeModal(SMART_BLOCK_COLUMN_SIZE_DROPDOWN_ID)
        : modals.openModal({
            id: SMART_BLOCK_COLUMN_SIZE_DROPDOWN_ID,
            Component: ColumnSizeDropdown,
            componentProps,
            layout: services.context.isMobile ? 'drawer' : 'floating',
            positioning: { referenceElement, placement: 'bottom' },
            type: 'exclusive',
            onClickOutside: {
              on: 'pointerup',
              handler: e => {
                if (!referenceElement?.contains?.(e.target as Node)) {
                  modals.closeModal(SMART_BLOCK_COLUMN_SIZE_DROPDOWN_ID);
                  return;
                }
              },
            },
          });
    },
    getComponentProps: ({ tiptapEditor, modals, attributes, t }) => ({
      dropdownOptions: Object.entries(COLUMN_SIZE_OPTIONS).map(([key, option]) => ({
        id: key,
        dataHook: option.dataHook,
        label: t(option.label),
        icon: option.icon,
        iconMobile: option.iconMobile,
      })),
      onSelect: size => {
        tiptapEditor.commands.setSmartBlockColumnSize(size as SmartBlockData_ColumnSize);
        modals.closeModal(SMART_BLOCK_COLUMN_SIZE_DROPDOWN_ID);
      },
      selectedId: getSelectedColumnSize(attributes.selectedNode as PmNode | undefined),
      closeModal: () => modals.closeModal(SMART_BLOCK_COLUMN_SIZE_DROPDOWN_ID),
    }),
  });

type ColumnSizeDropdownProps = {
  dropdownOptions: {
    id: string;
    dataHook: string;
    label: string;
    icon: React.ComponentType;
    iconMobile: React.ComponentType;
  }[];
  onSelect: (value: string) => void;
  selectedId?: string;
  closeModal: () => void;
};

const ColumnSizeDropdown: React.FC<ColumnSizeDropdownProps> = ({
  dropdownOptions,
  selectedId,
  closeModal,
  onSelect,
}) => {
  const { isMobile, t } = useContext(RicosContext);

  return (
    <DropdownModal
      onCloseButtonClick={closeModal}
      title={t('SmartBlock_ColumnSize_Title')}
      options={dropdownOptions.map(
        ({ id: commandKey, dataHook, label, icon: Icon, iconMobile: IconMobile }) => (
          <ListItemSelect
            key={commandKey}
            dataHook={dataHook}
            prefix={isMobile && IconMobile ? <IconMobile /> : Icon ? <Icon /> : null}
            title={label}
            selected={commandKey === selectedId}
            onSelect={() => {
              onSelect(commandKey);
              closeModal();
            }}
          />
        )
      )}
    />
  );
};

const ColumnSizeButton: React.FC<{
  toolbarItem: IToolbarItem;
  id: string;
}> = ({ toolbarItem, id }) => {
  const isModalOpen = useModalState(getIsModalOpen(id));
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);
  const { t } = useContext(RicosContext);
  const selectedSize = getSelectedColumnSize(toolbarItem?.attributes?.selectedNode as PmNode);

  return (
    <DropdownButton
      dataHook={DATA_HOOKS.COLUMN_SIZE_DROPDOWN_BUTTON}
      active={isModalOpen}
      onClick={() => {
        toolbarItem.commands?.click({ referenceElement });
      }}
      icon={COLUMN_SIZE_OPTIONS[selectedSize].icon}
      ref={setReferenceElement}
      tooltip={t('SmartBlock_Toolbar_ColumnSize_Tooltip')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
