import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../../ricos-modals/modal-service-provider.js';
import type { SmartBlockData_Orientation } from './../../../ricos-schema/next-schema/index.js';
import type { IToolbarItem } from './../../../ricos-types/index.js';
import { DropdownButton } from './../../../_shared/dropdown-button.js';

import { DATA_HOOKS } from '../../data-hooks.js';
import {
  getSelectedOrientation,
  ORIENTATION_OPTIONS,
  SMART_BLOCK_ORIENTATION_DROPDOWN_ID,
} from '../orientation-options.js';

export const OrientationDropdownButton: React.FC<{ toolbarItem: IToolbarItem }> = ({
  toolbarItem,
}) => {
  const isModalOpen = useModalState(getIsModalOpen(SMART_BLOCK_ORIENTATION_DROPDOWN_ID));
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);
  const { t } = useContext(RicosContext);

  const orientation = getSelectedOrientation(
    toolbarItem.attributes.selectedNode?.attrs?.orientation as
      | SmartBlockData_Orientation
      | undefined
  );

  return (
    <DropdownButton
      dataHook={DATA_HOOKS.DIRECTION_DROPDOWN_BUTTON}
      active={isModalOpen}
      onClick={() => {
        toolbarItem.commands?.click({ referenceElement });
      }}
      icon={ORIENTATION_OPTIONS[orientation].icon}
      ref={setReferenceElement}
      tooltip={t('SmartBlock_Toolbar_Orientation_Tooltip')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
